<script setup lang="ts">
import {computed, onBeforeUnmount, ref} from 'vue';import {useRoute} from 'vue-router';import {fetchHttpClient, ApiHttpError} from '../../api/client';import {mockApi} from '../../api/mock';import FieldMapping from './FieldMapping.vue';import DatasetList from './DatasetList.vue';import ImportHealth from './ImportHealth.vue';
const route=useRoute();const projectId=computed(()=>String(route.params.p));const client=import.meta.env.VITE_USE_MOCK !== 'false' ? mockApi : fetchHttpClient();const abortController=new AbortController();const file=ref<File|null>(null),step=ref(1),busy=ref(false),error=ref('');onBeforeUnmount(()=>abortController.abort());
function choose(e:Event){const f=(e.target as HTMLInputElement).files?.[0]??null;error.value='';if(f&&!/\.(csv|xlsx|xls|txt)$/i.test(f.name)){error.value='仅支持 CSV、XLSX、XLS 或 TXT 文件';return}if(f&&f.size>20*1024*1024){error.value='文件大小不能超过 20 MB';return}file.value=f}
async function upload(){if(!file.value){error.value='请选择要导入的文件';return}busy.value=true;try{const d=await client.upload(projectId.value,file.value,abortController.signal);sessionStorage.setItem(`voicelens:dataset:${projectId.value}`,JSON.stringify(d));step.value=2}catch{error.value='上传失败，请稍后重试'}finally{busy.value=false}}
</script>
<template><section class="page" data-testid="import-page"><h1>数据导入</h1><p class="muted">项目：{{projectId}}</p><div class="steps">导入文件 → 字段映射 → 治理报告</div><div v-if="step===1" class="card"><input data-testid="file-input" type="file" accept=".csv,.xlsx,.xls,.txt" @change="choose"><p v-if="file">{{file.name}}</p><button data-testid="upload-button" :disabled="busy" @click="upload">{{busy?'上传中…':'开始上传'}}</button><p v-if="error" class="error" data-testid="import-error">{{error}}</p></div><FieldMapping v-else-if="step===2" @next="step=3"/><ImportHealth v-else @done="step=1"/><DatasetList :project-id="projectId"/></section></template>
